import { Client } from 'kubernetes-client';
export async function listPods() {
  try {
    const client = new Client({ version: '1.16' });
    client.loadFromString(`
      apiVersion: v1
      clusters:
      - cluster:
          certificate-authority-data: 
          server: https://74.220.22.188:6443
        name: dev
      contexts:
      - context:
          cluster: dev
          user: dev
        name: dev
      current-context: dev
      kind: Config
      preferences: {}
      users:
      - name: dev
        user:
        client-certificate-data: 
        client-key-data: 
    `);

    await client.loadSpec();
    const pods = await client.api.v1.pods.get();
    console.log('Pods:');
    console.log(pods.body.items);
   } catch (error) {
    console.error('Error:', error);
  }
}

listPods();
